import{_ as r,c as t,o as a,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"zfeed 总览","description":"","frontmatter":{"title":"zfeed 总览","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#1","branch":"main","level":0,"order":1},"headers":[],"relativePath":"posts/projects/zfeed/01-zfeed-overview/index.md","filePath":"posts/projects/zfeed/01-zfeed-overview/index.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/01-zfeed-overview/index.md"};function l(i,e,n,d,b,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="zfeed-总览" tabindex="-1">zfeed 总览 <a class="header-anchor" href="#zfeed-总览" aria-label="Permalink to &quot;zfeed 总览&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1" target="_blank" rel="noreferrer">deploy/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml" target="_blank" rel="noreferrer">deploy/docker-compose.yml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf" target="_blank" rel="noreferrer">deploy/nginx/default.conf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.mod" target="_blank" rel="noreferrer">go.mod</a></li></ul></details><p><code>zfeed</code> 是一个使用 Go、go-zero 微服务框架和 Docker Compose 构建的高性能内容社区系统。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L1-L7" target="_blank" rel="noreferrer">README.md#1-7</a> 它实现了一套现代社交媒体架构，覆盖内容发布、多策略 Feed 流、高频计数器和全文搜索。</p><p>系统采用微服务拓扑设计，将不同职责拆分到专门的 RPC 服务中，由 API 网关统一协调，并依托 MySQL、Redis、Kafka、Canal 等基础设施组件支撑运行。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L21-L30" target="_blank" rel="noreferrer">README.md#21-30</a></p><h3 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h3><ul><li>用户管理：注册、登录、会话处理和个人资料统计。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L34-L34" target="_blank" rel="noreferrer">README.md#34</a></li><li>内容生命周期：支持文章和视频发布，并提供复杂的详情聚合能力。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L35-L35" target="_blank" rel="noreferrer">README.md#35</a></li><li>Feed 系统：推荐流（热门内容排序）、基于关注关系的收件箱，以及面向用户的个性化 Feed。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L36-L36" target="_blank" rel="noreferrer">README.md#36</a></li><li>社交互动：原子化的点赞/取消点赞流程、楼中楼评论，以及收藏/关注系统。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L37-L37" target="_blank" rel="noreferrer">README.md#37</a></li><li>搜索与发现：通过 Redis 快照为用户搜索和内容搜索提供稳定分页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L39-L39" target="_blank" rel="noreferrer">README.md#39</a></li><li>可观测性：集成 Prometheus 指标、Jaeger 链路追踪和结构化日志。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L40-L40" target="_blank" rel="noreferrer">README.md#40</a></li></ul><p>系统搭建指南请参阅<a href="./01-getting-started.html">快速开始</a>。</p><hr><h3 id="服务拓扑" tabindex="-1">服务拓扑 <a class="header-anchor" href="#服务拓扑" aria-label="Permalink to &quot;服务拓扑&quot;">​</a></h3><p>系统由一个 API 网关（<code>front-api</code>）和六个专门的 RPC 服务组成。这些服务通过 gRPC 通信，并使用 Etcd 进行服务发现。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L21-L36" target="_blank" rel="noreferrer">deploy/docker-compose.yml#21-36</a></p><table tabindex="0"><thead><tr><th>服务</th><th>端口</th><th>主要职责</th></tr></thead><tbody><tr><td><code>front-api</code></td><td><code>5000</code></td><td>HTTP 入口、认证中间件、RPC 聚合。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L25-L25" target="_blank" rel="noreferrer">README.md#25</a></td></tr><tr><td><code>user-rpc</code></td><td><code>5003</code></td><td>身份认证、会话、个人资料管理。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L26-L26" target="_blank" rel="noreferrer">README.md#26</a></td></tr><tr><td><code>content-rpc</code></td><td><code>5001</code></td><td>内容生命周期、Feed 生成、热门排序。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L27-L27" target="_blank" rel="noreferrer">README.md#27</a></td></tr><tr><td><code>interaction-rpc</code></td><td><code>5002</code></td><td>点赞、评论、收藏、关注。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L28-L28" target="_blank" rel="noreferrer">README.md#28</a></td></tr><tr><td><code>count-rpc</code></td><td><code>5004</code></td><td>高频计数器、基于 Canal 的 CDC。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L29-L29" target="_blank" rel="noreferrer">README.md#29</a></td></tr><tr><td><code>search-rpc</code></td><td><code>5006</code></td><td>全文搜索、结果缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L30-L30" target="_blank" rel="noreferrer">README.md#30</a></td></tr></tbody></table><h4 id="系统组件图" tabindex="-1">系统组件图 <a class="header-anchor" href="#系统组件图" aria-label="Permalink to &quot;系统组件图&quot;">​</a></h4><p>下图将高层系统组件映射到对应的代码实体与基础设施依赖。</p><p>图：系统组件映射</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L1-L36" target="_blank" rel="noreferrer">deploy/docker-compose.yml#1-36</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L23-L70" target="_blank" rel="noreferrer">deploy/nginx/default.conf#23-70</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L23-L30" target="_blank" rel="noreferrer">README.md#23-30</a></p><hr><h3 id="架构与数据流" tabindex="-1">架构与数据流 <a class="header-anchor" href="#架构与数据流" aria-label="Permalink to &quot;架构与数据流&quot;">​</a></h3><p>zfeed 同时使用同步 gRPC 调用和异步事件驱动模式：前者满足即时数据需求，后者处理计数、搜索索引等衍生影响。</p><ol><li>请求聚合：<code>front-api</code> 充当 Backend-for-Frontend（BFF），聚合多个 RPC 服务的数据。例如，<code>GetContentDetail</code> 会并发调用 <code>user-rpc</code> 获取作者信息、调用 <code>count-rpc</code> 获取统计数据，并调用 <code>interaction-rpc</code> 获取当前浏览者的点赞/关注状态。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L180-L212" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#180-212</a></li><li>事件驱动计数器：当用户点赞一篇内容时，<code>interaction-rpc</code> 会写入 MySQL。Canal 监听 MySQL binlog 并将事件发布到 Kafka，随后 <code>count-rpc</code> 消费这些事件，更新 <code>zfeed_count_value</code> 中的高频计数器。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L29-L29" target="_blank" rel="noreferrer">README.md#29</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L5-L15" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#5-15</a></li><li>搜索与分页：<code>search-rpc</code> 使用 Redis 快照管理稳定分页，确保新内容持续发布时，用户不会看到重复项或漏掉结果。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L30-L30" target="_blank" rel="noreferrer">README.md#30</a></li></ol><p>图：数据流与实体交互</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L180-L212" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#180-212</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L23-L30" target="_blank" rel="noreferrer">README.md#23-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L5-L15" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#5-15</a></p><p>如需深入了解服务拓扑与基础设施，请参阅<a href="./02-system-architecture.html">系统架构</a>。</p><hr><h3 id="可观测性栈" tabindex="-1">可观测性栈 <a class="header-anchor" href="#可观测性栈" aria-label="Permalink to &quot;可观测性栈&quot;">​</a></h3><p>系统已接入生产级监控所需的观测能力。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L29-L71" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#29-71</a></p><ul><li>指标：自定义 Prometheus 直方图和计数器（例如 <code>zfeed_search_request_duration_ms</code>）用于追踪延迟与错误率。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L30-L37" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#30-37</a></li><li>链路追踪：OpenTelemetry（OTEL）采集器将 trace 转发到 Jaeger，用于可视化跨服务请求链路。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L167-L190" target="_blank" rel="noreferrer">deploy/docker-compose.yml#167-190</a></li><li>日志：各服务输出结构化 JSON 日志，并可通过 Filebeat/Logstash 管道进行聚合。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L49-L50" target="_blank" rel="noreferrer">deploy/.env#49-50</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L16-L31" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#16-31</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L1-L71" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#1-71</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L35-L59" target="_blank" rel="noreferrer">deploy/.env#35-59</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L4-L31" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#4-31</a></p>',27)])])}const g=r(c,[["render",l]]);export{f as __pageData,g as default};
